sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */

	// Get my team review by status
	data.isManager = checkIfManager(gs.getUserID());

	if(data.isManager) {
		data.myteamreviews_by_status = getMyTeamsCurrentReview(gs.getUserID());
	}

	function getOptionItems(field) {
		var inData = [];
		var language = gs.getSession().getLanguage();
		var choices = GlideChoiceList.getChoiceList("x_snc_createnotes_note", field);
		var obj={};
		var grForLabels = new GlideRecord("x_snc_createnotes_note");

		for (i = 0; i < choices.getSize(); i++){
			obj.value = choices.getChoice(i).getValue();
			if(obj.value) {
				obj.label = choices.getChoice(i).getLabel();
				inData.push(obj);
				obj={};
			}
		}

		return inData;
	}

	data.review_states = getOptionItems('review_state');
	console.log(">---------------");
	console.log(data.review_states);
	console.log("---------------<");

	function getMyTeamsCurrentReview(userID) {
		var arrResult = [];
		var currentDate = new GlideDateTime();
		var currentYear = currentDate.getYearUTC();

		var grReviewsByStatus = new GlideAggregate('x_snc_createnotes_note');
		grReviewsByStatus.addAggregate("count","review_state");
		grReviewsByStatus.orderBy(("review_state"));
		grReviewsByStatus.addEncodedQuery('collaborator.managerDYNAMIC' + userID + '^review_year=' + currentYear); 
		grReviewsByStatus.query();
		while (grReviewsByStatus.next()) {
			//do things on the results
			var reviewCount = grReviewsByStatus.getAggregate('COUNT', 'review_state');
			console.log('LOG - Display the count for: ' + grReviewsByStatus.review_state.getDisplayValue() + ' is ' + reviewCount);
			arrResult.push(
				{
					"state":grReviewsByStatus.review_state.getDisplayValue(), 
					"count":reviewCount
				}
			);
		}

		return arrResult;
	}

	function checkIfManager(inUser) {
		var retValue = false;
		var grSysUser = new GlideRecord('sys_user');
		grSysUser.addEncodedQuery("manager=" + inUser + "^active=true");
		grSysUser.query();
		if(grSysUser.getRowCount() > 0) {
			retValue = true
		}

		return retValue;
	}


})();
